'use strict';
const $=id=>document.getElementById(id),canvas=$('poster'),ctx=canvas.getContext('2d');
const fieldIds=['nickname','intention','platform','days','quantity','barrier','response','vision'];
const font='"Microsoft YaHei","PingFang SC",sans-serif';
const bg=new Image();bg.src='data:image/png;base64,';
let faceImage=null,faceLoading=false,faceToken=0,downloadURL=null,generated=false;
const displayValue=id=>$(id).value.trim()||$(id).placeholder;
const titleText=()=>`${displayValue('nickname')}的垃圾帖挑战意图卡`;
function validNumber(id){const e=$(id),n=Number(e.value);return e.value.trim()!==''&&Number.isInteger(n)&&n>=Number(e.min)&&n<=Number(e.max)?n:null}
function rate(){const d=validNumber('days'),n=validNumber('quantity');if(d===null||n===null)return null;return Number((n/d).toFixed(n/d<.01?4:2)).toLocaleString('zh-CN',{maximumFractionDigits:4})}
function lines(text,width,size=29,weight=''){ctx.font=`${weight} ${size}px ${font}`;const result=[];for(const p of text.split('\n')){let line='';for(const ch of p){if(line&&ctx.measureText(line+ch).width>width){if('，。！？；：、）》】…'.includes(ch)&&Array.from(line).length>1){const tail=Array.from(line).pop();result.push(line.slice(0,-tail.length));line=tail+ch}else{result.push(line);line=ch}}else line+=ch}result.push(line)}return result}
function txt(value,x,y,size=29,color='#244f3c',weight='',align='left'){ctx.fillStyle=color;ctx.textAlign=align;ctx.font=`${weight} ${size}px ${font}`;ctx.fillText(value,x,y)}
function rule(y){ctx.strokeStyle='#cbd5bf';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(76,y);ctx.lineTo(1004,y);ctx.stroke()}
function flow(value,x,y,width,size=29,step=47,weight=''){for(const line of lines(value,width,size,weight)){txt(line,x,y,size,'#244f3c',weight);y+=step}return y}
function syncHeading(){const h=$('page-title');h.textContent=titleText();let size=42;h.style.fontSize=size+'px';while(h.scrollWidth>h.clientWidth&&size>13){size--;h.style.fontSize=size+'px'}}
function render(){
 const hasFace=!!faceImage&&document.querySelector('input[name="face-mode"]:checked').value==='add';
 const a=displayValue('intention'),barrier=$('barrier').value.trim(),response=$('response').value.trim(),v=displayValue('vision');
 const hasCoping=!!(barrier||response),paired=!!(barrier&&response),copingWidth=paired?428:928;
 const aLines=lines(a,928),bLines=lines(barrier,copingWidth,29),rLines=lines(response,copingWidth,29),vWidth=hasFace?576:928,vLines=lines(v,vWidth);
 const intentionY=292,actionY=intentionY+65+aLines.length*47+36;
 const planHeight=Math.max(137,82+lines(displayValue('platform'),267,33,'600').length*43);
 const copingY=actionY+planHeight+148;
 const copingRows=paired?Math.max(bLines.length,rLines.length):(barrier?bLines.length:rLines.length);
 const visionY=hasCoping?copingY+122+copingRows*47+65:copingY;
 const faceBoxHeight=hasFace?Math.min(346,300*faceImage.naturalHeight/faceImage.naturalWidth):0;
 const visionBodyHeight=Math.max(vLines.length*47,hasFace?faceBoxHeight+45:0);
 const height=Math.max(1160,visionY+118+visionBodyHeight+178);
 canvas.width=1080;canvas.height=height;
 paintBackground(height);
 if(window.INTENTION_EXAMPLE)txt('填写范例',76,70,20,'#708367');
 txt('喜多的工作坊：垃圾帖宝藏场',540,70,22,'#708367','','center');
 let titleSize=54;ctx.font=`600 ${titleSize}px ${font}`;while(ctx.measureText(titleText()).width>936&&titleSize>22){titleSize--;ctx.font=`600 ${titleSize}px ${font}`}txt(titleText(),540,171,titleSize,'#244f3c','600','center');
 rule(222);
 txt('01',76,intentionY,20,'#819472');txt('设立意图',127,intentionY,32,'#61785a','600');flow(a,76,intentionY+65,928);rule(actionY-31);
 txt('02',76,actionY,20,'#819472');txt('执行意图',127,actionY,32,'#61785a','600');
 const d=validNumber('days'),n=validNumber('quantity'),avg=rate();
 const metrics=[['发布平台',displayValue('platform')],['挑战周期',d===null?$('days').placeholder+' 天':`${d} 天`],['计划总数',n===null?$('quantity').placeholder+' 条':`${n.toLocaleString('zh-CN')} 条`]];
 ctx.fillStyle='rgba(217,230,202,.64)';ctx.fillRect(76,actionY+30,928,planHeight);
 for(let i=0;i<3;i++){const x=106+i*306;txt(metrics[i][0],x,actionY+72,22,'#718467');flow(metrics[i][1],x,actionY+128,267,33,43,'600')}
 txt(avg===null?'填写周期与总数后，自动计算日均节奏':`平均每天约 ${avg} 条，按自己的节奏发布即可`,76,actionY+planHeight+74,22,'#718467');
 if(hasCoping){
  rule(copingY-42);txt('03',76,copingY,20,'#819472');txt('应对计划',127,copingY,32,'#61785a','600');
  if(barrier){txt('可能的阻碍：',76,copingY+65,29,'#718467');flow(barrier,76,copingY+122,copingWidth,29,47)}
  if(response){const x=paired?576:76;txt('这时候我会这么做：',x,copingY+65,29,'#718467');flow(response,x,copingY+122,copingWidth,29,47)}
 }
 rule(visionY-42);txt(hasCoping?'04':'03',76,visionY,20,'#819472');txt('愿景期待',127,visionY,32,'#61785a','600');
 txt('想象挑战终点的自己，写下你期待的变化。',76,visionY+52,22,'#718467');flow(v,76,visionY+105,vWidth);
 if(hasFace){const box={x:704,y:visionY+82,w:300,h:faceBoxHeight};ctx.fillStyle='#fffdf5';ctx.fillRect(box.x-12,box.y-12,box.w+24,box.h+24);const scale=Math.min(box.w/faceImage.naturalWidth,box.h/faceImage.naturalHeight),iw=faceImage.naturalWidth*scale,ih=faceImage.naturalHeight*scale;ctx.drawImage(faceImage,box.x+(box.w-iw)/2,box.y+(box.h-ih)/2,iw,ih);txt(window.INTENTION_EXAMPLE?'人物示意卡（可替换）':'我选中的 Faces 卡',854,box.y+box.h+40,19,'#718467','','center')}
 rule(height-128);txt('允许自己先写出垃圾，看里面藏着什么宝藏',540,height-67,23,'#6c815f','','center');ctx.textAlign='left';
 $('coping-number').textContent=hasCoping?'03':'＋';$('vision-number').textContent=hasCoping?'04':'03';
 syncHeading();$('daily-rate').textContent=avg===null?'填写天数和总数后，自动计算每天的平均条数':`平均每天约 ${avg} 条（计划总数 ÷ 天数）`;
}
function paintBackground(height){
 const paper='#faf8ef';ctx.fillStyle=paper;ctx.fillRect(0,0,1080,height);
 if(!bg.complete||!bg.naturalWidth)return;
 const imageHeight=1080*bg.naturalHeight/bg.naturalWidth;
 ctx.save();ctx.beginPath();ctx.rect(0,0,1080,225);ctx.clip();ctx.drawImage(bg,0,0,1080,imageHeight);ctx.restore();
 ctx.save();ctx.beginPath();ctx.rect(0,height-180,1080,180);ctx.clip();ctx.drawImage(bg,0,height-imageHeight,1080,imageHeight);ctx.restore();
 const top=ctx.createLinearGradient(0,140,0,225);top.addColorStop(0,'rgba(250,248,239,0)');top.addColorStop(1,paper);ctx.fillStyle=top;ctx.fillRect(0,140,1080,85);
 const bottom=ctx.createLinearGradient(0,height-180,0,height-100);bottom.addColorStop(0,paper);bottom.addColorStop(1,'rgba(250,248,239,0)');ctx.fillStyle=bottom;ctx.fillRect(0,height-180,1080,80);
}
function status(message){$('status').textContent=message}
function clearDownload(){if(downloadURL)URL.revokeObjectURL(downloadURL);downloadURL=null;$('image-link').hidden=true}
function changed(){generated=false;clearDownload();render();status('预览已同步。确认内容后，生成并保存。')}
fieldIds.forEach(id=>$(id).addEventListener('input',changed));
function clearFace(){faceToken++;faceImage=null;faceLoading=false;$('face-file').value='';$('face-preview').removeAttribute('src');$('face-preview-wrap').hidden=true;$('upload-status').textContent='';changed()}
document.querySelectorAll('input[name="face-mode"]').forEach(e=>e.addEventListener('change',()=>{$('upload-panel').hidden=e.value!=='add';if(e.value==='none')clearFace();else changed()}));
$('remove-face').addEventListener('click',clearFace);
$('face-file').addEventListener('change',async()=>{const file=$('face-file').files[0];if(!file)return;const token=++faceToken;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>12*1024*1024){$('upload-status').textContent='请选择不超过 12 MB 的 JPG、PNG 或 WebP 图片。';$('face-file').value='';return}faceLoading=true;generated=false;clearDownload();$('upload-status').textContent='正在准备图片……';try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});const original=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=data});if(token!==faceToken)return;if(original.naturalWidth*original.naturalHeight>60000000)throw new Error('too-large');const scale=Math.min(1,1600/Math.max(original.naturalWidth,original.naturalHeight)),temp=document.createElement('canvas');temp.width=Math.max(1,Math.round(original.naturalWidth*scale));temp.height=Math.max(1,Math.round(original.naturalHeight*scale));temp.getContext('2d').drawImage(original,0,0,temp.width,temp.height);const resized=new Image();await new Promise((resolve,reject)=>{resized.onload=resolve;resized.onerror=reject;resized.src=temp.toDataURL('image/png')});if(token!==faceToken)return;faceImage=resized;$('face-preview').src=resized.src;$('face-preview-wrap').hidden=false;$('upload-status').textContent='图片已加入海报，完整保留卡面。';faceLoading=false;changed()}catch(e){if(token!==faceToken)return;faceLoading=false;$('upload-status').textContent='这张图片暂时无法读取，请换一张 JPG、PNG 或 WebP。';$('face-file').value=''}});
$('intent-form').addEventListener('submit',e=>{e.preventDefault();const labels={nickname:'昵称',intention:'设立意图',platform:'发布平台',vision:'愿景期待'},missing=Object.keys(labels).find(id=>!$(id).value.trim());if(missing){status('请填写'+labels[missing]+'。');$(missing).focus();return}if(validNumber('days')===null||validNumber('quantity')===null){status('天数和计划总数量都需要填写正整数。');return}if(faceLoading){status('图片仍在准备，请稍等片刻再生成。');return}render();generated=true;status('意图卡已生成。检查无误后保存图片，分享到群里。');$('preview').scrollIntoView({behavior:'smooth',block:'start'})});
$('download').addEventListener('click',()=>{if(!generated){$('intent-form').requestSubmit();return}canvas.toBlob(blob=>{if(!blob){status('图片生成失败，请再试一次。');return}clearDownload();downloadURL=URL.createObjectURL(blob);const link=document.createElement('a');link.href=downloadURL;link.download=titleText()+'.png';document.body.append(link);link.click();link.remove();$('image-link').href=downloadURL;$('image-link').hidden=false;status('图片已准备好。手机若未自动下载，可打开下方图片链接后长按保存。')},'image/png')});
$('edit').addEventListener('click',()=>{$('intent-form').scrollIntoView({behavior:'smooth'});$('nickname').focus({preventScroll:true})});
bg.onload=render;bg.onerror=render;document.fonts.ready.then(render);window.addEventListener('resize',syncHeading);render();
